import type { FC } from 'react';
import { motion } from 'framer-motion';
import Certifications from '../components/Certifications';

const CertificationsPage: FC = () => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="pt-24"
    >
      <Certifications />
    </motion.div>
  );
};

export default CertificationsPage;
