import type { FC, MouseEvent } from 'react';
import { useRef } from 'react';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { Award } from 'lucide-react';
import { Card, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import portfolioData from '../data/portfolio.json';

interface Certification {
  title: string;
  issuer: string;
  date: string;
  badge?: string;
}

interface CertificationCardProps {
  cert: Certification;
  index: number;
}

const CertificationCard: FC<CertificationCardProps> = ({ cert, index }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const pointerX = useMotionValue(0);
  const pointerY = useMotionValue(0);
  const springConfig = { stiffness: 220, damping: 20, mass: 0.6 };
  const rotateX = useSpring(useTransform(pointerY, [-0.5, 0.5], [10, -10]), springConfig);
  const rotateY = useSpring(useTransform(pointerX, [-0.5, 0.5], [-10, 10]), springConfig);
  const translateY = useSpring(useTransform(pointerY, [-0.5, 0.5], [6, -6]), springConfig);

  const handleMouseMove = (event: MouseEvent<HTMLDivElement>) => {
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    pointerX.set((event.clientX - rect.left) / rect.width - 0.5);
    pointerY.set((event.clientY - rect.top) / rect.height - 0.5);
  };

  const handleMouseLeave = () => {
    pointerX.set(0);
    pointerY.set(0);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.1 }}
      style={{ perspective: 1000 }}
      className="h-full"
    >
      <motion.div
        ref={cardRef}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{ rotateX, rotateY, y: translateY, transformStyle: 'preserve-3d' }}
        whileHover={{ scale: 1.03 }}
        transition={{ type: 'spring', stiffness: 220, damping: 20 }}
        className="h-full"
      >
        <Card className="h-full overflow-hidden glass-panel hover:shadow-glow border-0 transition-shadow duration-300">
          <CardHeader className="pb-2 flex flex-col items-center">
            <div className="flex justify-center items-center mb-3 h-24">
              {cert.badge ? (
                <img
                  src={cert.badge}
                  alt={`${cert.title} badge`}
                  width={96}
                  height={96}
                  loading="lazy"
                  decoding="async"
                  className="w-16 h-16 sm:w-20 sm:h-20 md:w-24 md:h-24 object-contain drop-shadow-lg"
                />
              ) : (
                <div className="bg-accent/10 w-14 h-14 sm:w-16 sm:h-16 md:w-20 md:h-20 rounded-full flex items-center justify-center">
                  <Award className="text-accent w-8 h-8 sm:w-10 sm:h-10 md:w-12 md:h-12" />
                </div>
              )}
            </div>
            <CardTitle className="text-base md:text-lg text-center line-clamp-2">{cert.title}</CardTitle>
            <CardDescription className="text-center text-sm">{cert.issuer} • {cert.date}</CardDescription>
          </CardHeader>
        </Card>
      </motion.div>
    </motion.div>
  );
};

const Certifications: FC = () => {
  return (
    <section className="section-container pt-0 pb-12 md:py-1">
      <div className="text-center mb-8 md:mb-12">
        <h1 className="text-2xl md:text-3xl font-display font-medium mb-6 text-accent break-words">
          Certifications
        </h1>
        <p className="text-muted-foreground max-w-2xl mx-auto text-xl font-light leading-relaxed">
          certified, verified, battle-tested
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 max-w-7xl mx-auto px-4">
        {portfolioData.certifications.map((cert: Certification, index) => (
          <CertificationCard key={cert.title} cert={cert} index={index} />
        ))}
      </div>
    </section>
  );
};

export default Certifications;
